const examples={leave:{q:'How do I request leave?',a:'Submit a leave request to your team lead at least five working days in advance. Once approved, add it to the shared team calendar.',source:'Team handbook · Leave policy',excerpt:'Fictional handbook, section 2.1: Leave requests should reach the team lead at least five working days before the first day off. Approved leave must be recorded in the shared team calendar.'},expenses:{q:'How do I claim a business expense?',a:'Upload your receipt and a short business justification to the expense form. Your manager reviews it before it goes to finance for reimbursement.',source:'Team handbook · Expenses',excerpt:'Fictional handbook, section 3.2: Attach a receipt and business justification to the expense form. Claims require manager approval before finance processes reimbursement.'},unknown:{q:'What is our travel allowance for next year?',a:"I couldn't find a travel allowance for next year in the example handbook. Please check with your team lead or finance rather than relying on an unverified answer.",source:null,excerpt:''}};
const sourceToggle=document.getElementById('source-toggle');
const sourcePanel=document.getElementById('demo-source');
function showExample(key){const e=examples[key];document.getElementById('demo-question').textContent=e.q;document.getElementById('demo-answer').textContent=e.a;sourceToggle.hidden=!e.source;sourceToggle.style.display=e.source?'flex':'none';document.getElementById('source-name').textContent=e.source||'';sourcePanel.textContent=e.excerpt;sourcePanel.hidden=true;sourceToggle.setAttribute('aria-expanded','false');document.querySelectorAll('[data-question]').forEach(b=>{const active=b.dataset.question===key;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>showExample(b.dataset.question)));
sourceToggle.addEventListener('click',()=>{sourcePanel.hidden=!sourcePanel.hidden;sourceToggle.setAttribute('aria-expanded',String(!sourcePanel.hidden));});
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.getElementById('service').value=a.dataset.service;}));
document.getElementById('enquiry-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const name=String(data.get('name')).trim();const brief=String(data.get('brief')).trim();if(!name||brief.length<15){document.getElementById('brief').setCustomValidity('Please describe the problem in at least 15 characters.');document.getElementById('brief').reportValidity();return;}document.getElementById('brief').setCustomValidity('');const company=String(data.get('company')).trim();const message=`Hi Shakeel, I'm ${name}${company?' from '+company:''}.\n\nI'm interested in: ${data.get('service')}.\n\nProblem: ${brief}\n\nCan we discuss a focused pilot?`;window.open('https://wa.me/923198492624?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');});
document.getElementById('brief').addEventListener('input',e=>e.target.setCustomValidity(''));
showExample('leave');
